import math

def is_prime(n):
    """Checks if a number n is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def is_perfect_cube(n):
    """Checks if n is a perfect cube and returns the cube root if it is."""
    if n < 0:
        return None

    # Use round() after cube root calculation for robustness against floating point errors
    # We only care about positive integers here since q >= 2.
    root = round(n**(1/3))

    if root * root * root == n:
        return int(root)
    return None

# Search limit
LIMIT = 500
solutions = []

print(f"Starting search for prime q up to {LIMIT}...")

for q in range(2, LIMIT + 1):
    if is_prime(q):
        # 1. Calculate N = q^2 - q + 1
        N = q*q - q + 1

        # 2. Check if N is a perfect cube p^3
        p = is_perfect_cube(N)

        if p is not None:
            # 3. Verify p is prime and p != q
            if is_prime(p) and p != q:
                solutions.append((q, p))
                print(f"Solution found: q={q}, p={p}, N={N}")

print("\n--- Search complete ---")
if solutions:
    print("Solutions found:")
    for q, p in solutions:
        print(f"(q, p) = ({q}, {p})")
else:
    print("No new solutions found in the range q <= 500.")
